#!/usr/bin/env node
// Generated by OrchestKit Claude Plugin
// Created: 2026-08-06
//
// =============================================================================
// package.json and package-lock.json must agree on the version
// =============================================================================
// release-please owns the version and bumps every path listed in
// .release-please-config.json `extra-files`. package.json was listed there;
// package-lock.json was NOT, and a lockfile carries the version TWICE:
//
//     $.version                 and     $.packages[''].version
//
// So every release left the lockfile behind. Measured 2026-08-06 at
// origin/main 1f4cf6125: package.json said 9.7.0, package-lock.json said
// 9.5.2, two whole minor versions stale.
//
// WHY THIS IS WORTH A BLOCKING GATE, and not just a tidy-up:
// npm rewrites those fields on the next `npm install`. Every fresh clone and
// every new git worktree therefore came up with a MODIFIED package-lock.json
// before anyone had touched a line of code. A tree that is dirty on arrival
// trains everybody to wave dirt through, which is exactly how a real change
// gets discarded as "just the usual lockfile noise". It cost two reverts in
// one session before anyone asked why it kept coming back.
//
// The config now lists package-lock.json under both json paths, so
// release-please keeps them in step. This test is the backstop that proves it,
// because a config entry that silently stops matching is the same class of
// invisible failure.
// =============================================================================

import { readFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { dirname, join } from 'node:path';

const ROOT = join(dirname(fileURLToPath(import.meta.url)), '..', '..');
const read = (p) => JSON.parse(readFileSync(join(ROOT, p), 'utf8'));

const RED = '\x1b[0;31m';
const GREEN = '\x1b[0;32m';
const NC = '\x1b[0m';

let failed = 0;
const pass = (m) => console.log(`  ${GREEN}✓${NC} ${m}`);
const fail = (m) => {
  console.log(`  ${RED}✗${NC} ${m}`);
  failed = 1;
};

console.log('==========================================');
console.log('  Version consistency: package + lockfile');
console.log('==========================================');

const pkg = read('package.json');
const lock = read('package-lock.json');

const expected = pkg.version;
const lockTop = lock.version;
const lockRoot = lock.packages?.['']?.version;

if (lockTop === expected) {
  pass(`package-lock.json $.version matches package.json (${expected})`);
} else {
  fail(`package-lock.json $.version is ${lockTop}, package.json is ${expected}`);
}

if (lockRoot === expected) {
  pass(`package-lock.json $.packages[''].version matches (${expected})`);
} else {
  fail(`package-lock.json $.packages[''].version is ${lockRoot}, package.json is ${expected}`);
}

// The gate above only holds while release-please is actually told to bump the
// lockfile. Assert the config entries exist, so removing them fails HERE with a
// clear reason instead of silently reopening the drift one release later.
const cfg = read('.release-please-config.json');
const extras = cfg.packages?.['.']?.['extra-files'] ?? [];
const lockPaths = extras
  .filter((e) => e && e.path === 'package-lock.json')
  .map((e) => e.jsonpath);

for (const needed of ["$.version", "$.packages[''].version"]) {
  if (lockPaths.includes(needed)) {
    pass(`release-please governs package-lock.json ${needed}`);
  } else {
    fail(
      `release-please-config.json is missing an extra-files entry for ` +
        `package-lock.json ${needed} — the drift will silently return`,
    );
  }
}

console.log('');
if (failed) {
  console.log(`${RED}✗ Version consistency FAILED${NC}`);
  console.log('  Fix: run `npm install` to resync the lockfile, and commit it.');
} else {
  console.log(`${GREEN}✓ Version consistency passed${NC}`);
}
process.exit(failed);
